async function executeQuery(query) {
  const client = new Client({
    user: 'yourUser',
    host: 'yourHost',
    database: 'yourDatabase',
    password: 'yourPassword',
    port: 5432,
  });
  await client.connect();
  const res = await client.query(query);
  await client.end();
  return res.rows;
